node -e "
const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');

// Get all cart items with their prices to recalculate
const items = db.prepare(\"SELECT ci.*, p.price FROM cart_items ci JOIN products p ON ci.product_id = p.product_id WHERE ci.cart_id = 'CART-user_58b0a2d6'\").all();
console.log('Current items:', JSON.stringify(items, null, 2));

// Update quantity of the hoodie from 3 to 2
db.prepare(\"UPDATE cart_items SET quantity = 2 WHERE cart_item_id = 'CI-0006'\").run();

// Recalculate subtotal: Harbor Cotton Crew Tee (1 * price) + Hoodie (2 * 89) + Chino Pants (2 * price)
const updatedItems = db.prepare(\"SELECT ci.*, p.price FROM cart_items ci JOIN products p ON ci.product_id = p.product_id WHERE ci.cart_id = 'CART-user_58b0a2d6'\").all();
let newSubtotal = 0;
updatedItems.forEach(i => { newSubtotal += i.quantity * i.price; });
console.log('New subtotal:', newSubtotal);

// Get current cart to preserve other fields
const cart = db.prepare(\"SELECT * FROM carts WHERE cart_id = 'CART-user_58b0a2d6'\").get();
const newTotal = newSubtotal - cart.discount_amount + cart.gift_wrap_fee - cart.loyalty_discount + cart.shipping_cost;
console.log('New total:', newTotal);

// Update cart
db.prepare(\"UPDATE carts SET subtotal = ?, total = ? WHERE cart_id = 'CART-user_58b0a2d6'\").run(newSubtotal, newTotal);

// Verify
const finalCart = db.prepare(\"SELECT * FROM carts WHERE cart_id = 'CART-user_58b0a2d6'\").get();
const finalItems = db.prepare(\"SELECT ci.cart_item_id, ci.quantity, p.name, p.price FROM cart_items ci JOIN products p ON ci.product_id = p.product_id WHERE ci.cart_id = 'CART-user_58b0a2d6'\").all();
console.log('Final cart:', JSON.stringify(finalCart, null, 2));
console.log('Final items:', JSON.stringify(finalItems, null, 2));
"

